def solve(nums):
    # Handle empty or single-element list
    if len(nums) <= 1:
        return list(nums)
    a = nums[:]  # work on a copy
    n = len(a)
    # Find the first index from the right where a[i] < a[i+1]
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        # Last permutation: return sorted list
        return sorted(a)
    # Find the rightmost element greater than a[i]
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    # Swap them
    a[i], a[j] = a[j], a[i]
    # Reverse the suffix after position i
    a[i + 1:] = reversed(a[i + 1:])
    return a

